// 添付された追加カードデータを既存データへ統合する。
(function () {
  const norm = (value) => String(value || "").normalize("NFKC").toLowerCase().replace(/[\s・･－―—–ー_＿《》「」『』【】]/g, "");
  const rulings = window.RULINGS || (window.RULINGS = []);
  for (const source of window.CARD_DATA_ADDITIONS || []) {
    const item = rulings.find((candidate) => norm(candidate.name) === norm(source.name));
    if (!item) { rulings.push(source); continue; }
    for (const key of ["reading", "type", "spellType", "trapType", "cardClass", "environments", "image"]) {
      if (source[key] !== undefined) item[key] = source[key];
    }
    if (source.coverImage) { item.coverImage = source.coverImage; item.coverImageAlt = source.coverImageAlt; }
    if (source.overview !== undefined) item.overview = source.overview;
    if (source.related) item.related = [...new Set([...(item.related || []), ...source.related])];
    item.qa ||= [];
    for (const qa of source.qa || []) {
      const prior = item.qa.find((entry) => norm(entry.question) === norm(qa.question));
      if (prior) Object.assign(prior, qa); else item.qa.push(qa);
    }
  }
})();

